head.script:
scwin._checkHeader = function() {
	var gridViewBodyTable = WebSquare.wUnit.getJq("#test_body_table");
	if (gridViewBodyTable) {
    	var str = gridViewBodyTable.attr("summary") ?? "";
    	return arr = str.split(",");
	}
}
scwin.checkVal = function(domId, value) {
	if (WebSquare.util.isHTML5() === true) {
		return true;
	}
	return WebSquare.wUnit.getObjById($p.getFrameId() + "_" + domId).getAttribute('value') == value;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 summaryAuto 부분을 확인한다.
    //1. In the Source tab, check the summaryAuto section.
    //Verify 1. summaryAuto='true'
    //Test step 2. 브라우저에서 grid summaryAuto 결과 를 확인한다.
    //2. Check the grid summaryAuto results in your browser.
    //Verify 2. 각 헤더별로 ',(콤마)' 가 표시된다.
    //2. ', (comma)' is displayed for each header.
    WebSquare.wUnit.addCommand("set", "scwin._checkHeader()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal('test_column9', arr[0])", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal('test_column7', arr[1])", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal('test_column5', arr[2])", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal('test_column3', arr[3])", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal('test_column1', arr[4])", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.summary = WebSquare.wUnit.getJq("#test_body_table").attr("summary");
    sm.setValue(summary);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Feb-2018
    //End unitTest
    window.arr = undefined;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
